pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    TokenMock token;

    function setUp() public {
        c = new C("", 0, address(this));
        token = new TokenMock();
    }

    function testFuzz_property(
        uint256 sk,
        bool isCall,
        bool isLong,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 nonce
    ) public {
        sk = bound(sk, 1, type(uint256).max - 1);
        address maker = vm.addr(sk);
        duration = bound(duration, 0, 10_000 days - 1);
        uint256 expiration = block.timestamp + 1000;
        strike = bound(strike, 0, 1e30);
        premium = bound(premium, 0, 1e30);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: address(token),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(sk, orderHash);
        bytes memory signature = abi.encodePacked(r, s, v);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        c.fillOrder(order, signature, floorAssetTokenIds);

        uint256 positionId = uint256(c.hashOppositeOrder(order));
        bytes32 posHash = c.hashOppositeOrder(order);

        assertTrue(
            c.ownerOf(positionId) == address(this) && c.ownerOf(uint256(orderHash)) == maker && uint256(posHash) == positionId,
            "minted positions must be owned by their recipients"
        );
    }
}

